async (page) => {
  const select = async (name, label) => {
    await page.getByRole('combobox', { name, exact: true }).locator('xpath=ancestor::div[contains(@class, "el-select__wrapper")]').click();
    await page.getByRole('option', { name: label, exact: true }).click();
  };
  await page.getByRole('button', { name: '新建生成任务', exact: true }).click();
  await page.getByRole('button', { name: '动能定理', exact: true }).click();
  await select('年级', '高三');
  await select('题型', '多选题');
  await select('认知目标', '分析 · 拆解关系与过程');
  await select('目标难度', '困难');
  await page.getByRole('spinbutton', { name: '生成数量', exact: true }).fill('6');
  await page.getByRole('spinbutton', { name: '生成数量', exact: true }).press('Tab');
  if (await page.getByRole('spinbutton', { name: '生成数量', exact: true }).inputValue() !== '5') throw new Error('数量上限未生效');
  await page.getByRole('button', { name: '开始生成', exact: true }).click();
  await page.waitForURL(/task_id=/);
  const taskUrl = page.url();
  const taskId = new URL(taskUrl).searchParams.get('task_id');
  await page.getByRole('button', { name: '查看任务记录', exact: true }).click();
  await page.getByRole('textbox', { name: '搜索任务', exact: true }).fill('动能定理');
  if (await page.locator('.el-table__row').count() !== 1) throw new Error('知识点搜索不正确');
  await select('任务状态', '进行中');
  if (await page.locator('.el-table__row').count() !== 1) throw new Error('进行中筛选不正确');
  await page.getByRole('textbox', { name: '搜索任务', exact: true }).fill('不存在的演示命题');
  await page.getByText('没有找到匹配的任务', { exact: true }).waitFor();
  await page.getByRole('button', { name: '清除筛选', exact: true }).click();
  if (await page.locator('.el-table__row').count() !== 8) throw new Error('首页每页8条不正确');
  await page.getByRole('button', { name: '下一页', exact: true }).click();
  if (await page.locator('.el-table__row').count() !== 2) throw new Error('第二页结果数量不正确');
  await page.getByRole('button', { name: '上一页', exact: true }).click();
  await select('任务状态', '任务失败');
  if (await page.locator('.el-table__row').count() !== 3) throw new Error('任务失败筛选不正确');
  await select('任务状态', '全部任务');
  await page.getByRole('textbox', { name: '搜索任务', exact: true }).fill(taskId);
  await page.getByRole('button', { name: '查看详情', exact: true }).click();
  await page.waitForURL(/tasks\?task_id=/);
  await page.reload();
  await page.locator('.task-progress').getByText('任务完成', { exact: true }).waitFor({ timeout: 30000 });
  if (new URL(page.url()).searchParams.get('task_id') !== taskId) throw new Error('任务详情刷新丢失关联');
  const summary = await page.locator('.task-progress .summary-grid > div').allTextContents();
  const values = summary.map(value => Number(value.match(/\d+/)?.[0]));
  if (values.join(',') !== '5,5,0,0') throw new Error('5题批量结果异常：' + summary);
  await page.setViewportSize({ width: 1440, height: 1900 });
  await page.locator('.task-progress').scrollIntoViewIfNeeded();
  await page.screenshot({ path: 'output/playwright/task-list-five.png', fullPage: true });
  await page.goto('http://127.0.0.1:5180/tasks?task_id=TASK-UNAVAILABLE');
  await page.getByText('未找到该任务，或当前账号无法访问。请选择自己的任务记录。', { exact: true }).waitFor();
  if (await page.locator('.task-progress').count()) throw new Error('不存在的任务错误地显示了详情');
  return { generated: 5, saved: 5, selectedGrade: '高三', selectedType: 'multiple_choice', selectedBloom: 'analyze', selectedDifficulty: '困难', maxCountClamp: true, keywordSearch: true, ongoingFilter: true, failureFilter: true, pagination: [8, 2], detailRefresh: true, invalidTaskGuard: true, taskId };
}
